syntax:
template <typename T, typename U>
struct common_type {
    using type = decay_t<decltype(true ? declval<T>() : declval<U>())>;
};

code_example:
#include <type_traits>
template <class T, class U>
struct common_type {
    using type = decay_t<decltype(true ? declval<T>() : declval<U>())>;
};
int main() {
    static_assert(std::is_same<common_type<int, double>::type, double>::value, "Type mismatch");
    static_assert(std::is_same<common_type<int&, double>::type, double>::value, "Type mismatch");
    return 0;
}
